/**
 * Position Based Fluids (PBF) particle simulation that is purpose-built for GPU
 * constraint solving. It predicts velocities, enforces incompressibility via
 * density → lambda → position-delta iterations, and exposes an ergonomic API for
 * real-time fluid setups in Three Blocks.
 *
 * **Features**
 * - Deterministic velocity prediction + multi-iteration lambda solver with configurable passes
 * - Spatial grid acceleration (default) or naive O(N²) neighbor search
 * - 2D and 3D modes with adaptable kernel parameters
 * - Domain attachment to Three.js objects for dynamic boundary transforms
 * - Pointer-based interaction for user-driven forces
 * - Optional direction storage for oriented particle rendering
 *
 * **Notes**
 * - Shares kernel definitions (Poly6, Spiky) with the SPH module for material parity when switching solvers
 * @fileoverview Position Based Fluids (PBF) particle simulation optimized for GPU compute with optional spatial grid acceleration.
 *
 * ```js
 * import { PBF } from '@three-blocks/core';
 * import { SphereGeometry, InstancedMesh, MeshStandardNodeMaterial } from 'three/webgpu';
 * import { storage, instanceIndex } from 'three/tsl';
 *
 * const pbf = new PBF({
 *   count: 2000,
 *   is3D: true,
 *   domainDimensions: new THREE.Vector3(20, 20, 20),
 *   h: 1.2,
 *   viscosityMu: 0.15,
 *   useMatrices: true
 * });
 *
 * // Create instanced mesh for rendering particles
 * const geometry = new SphereGeometry(0.3, 8, 8);
 * const material = new MeshStandardNodeMaterial();
 * const positionNode = storage(pbf.buffers.positions, 'vec3', pbf.particleCount);
 * material.positionNode = positionNode.element(instanceIndex);
 * const mesh = new InstancedMesh(geometry, material, pbf.particleCount);
 * // When useMatrices is enabled, you can feed instance matrices directly
 * mesh.instanceMatrix = pbf.buffers.instanceMatrices.value;
 * scene.add(mesh);
 *
 * // Simulation loop
 * async function animate() {
 *   await pbf.step(renderer);
 *   renderer.render(scene, camera);
 *   requestAnimationFrame(animate);
 * }
 * ```
 *
 * @class PBF
 * @short GPU position-based fluids solver with optional spatial grid acceleration and domain binding.
 * @category Simulation
 * @tags WebGPU
 * @demo docs/demos/pbf.html
 * @see SpatialGrid
 */
